import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
// Replaced external dependency with inline SVG component to resolve "DollarSign is not defined"
const DollarSign: React.FC<{ size: number; color: string; strokeWidth?: number }> = ({ size, color, strokeWidth = 2 }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth={strokeWidth}
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <line x1="12" x2="12" y1="2" y2="22" />
    <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
  </svg>
);

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type MoneySprayProps = Record<string, any>;

const MoneySpray: React.FC<MoneySprayProps> = ({
  backgroundColor = "#111827",
  transparentBackground = false,
  durationInSeconds = 5,
  dollarColor = "#22c55e",
  glowColor = "#4ade80",
  moneyColor = "#86efac",
  iconSize = 300,
  sprayIntensity = 60,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Timing ---
  const entranceDelay = 5;
  const sprayStartFrame = 15;

  // --- Main Dollar Animation ---
  const scale = spring({
    frame: frame - entranceDelay,
    fps,
    config: {
      damping: 10,
      stiffness: 100,
      mass: 0.8,
    },
  });

  const opacity = interpolate(
    frame,
    [entranceDelay, entranceDelay + 10],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const glowRadius = interpolate(
    frame,
    [entranceDelay, entranceDelay + 20],
    [0, 40],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // --- Particle Logic (The "Spray") ---
  const particles = useMemo(() => {
    return new Array(sprayIntensity).fill(0).map((_, i) => {
      const seed = i * 1337;
      // Random angle: spread upwards (-PI to 0 mainly, but slightly constrained for a "fountain" effect)
      // We want it to spray UP (-PI/2) with some spread.
      const angle = interpolate(random(seed), [0, 1], [-Math.PI * 0.8, -Math.PI * 0.2]);
      const velocity = interpolate(random(seed + 1), [0, 1], [15, 35]); // Speed
      const rotationSpeed = interpolate(random(seed + 2), [0, 1], [-10, 10]);
      const size = interpolate(random(seed + 3), [0, 1], [width * 0.02, width * 0.04]);
      const delayOffset = interpolate(random(seed + 4), [0, 1], [0, 10]); // Slight stagger
      const hueShift = interpolate(random(seed + 5), [0, 1], [-20, 20]); // Color variation

      return { angle, velocity, rotationSpeed, size, delayOffset, hueShift };
    });
  }, [sprayIntensity, width]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>

      {/* 1. Money Particles (Rendered behind or around) */}
      {particles.map((p, i) => {
        const time = frame - sprayStartFrame - p.delayOffset;

        if (time < 0) return null;

        // Physics: Projectile motion
        // x = v * cos(theta) * t
        // y = v * sin(theta) * t + 0.5 * g * t^2
        const gravity = 1.5;
        const x = (width / 2) + Math.cos(p.angle) * p.velocity * time;
        const y = (height / 2) + Math.sin(p.angle) * p.velocity * time + (0.5 * gravity * time * time);

        const rotation = p.rotationSpeed * time;
        const particleOpacity = interpolate(time, [0, 10, 80, 100], [0, 1, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              width: p.size * 1.6, // Rectangular bill shape
              height: p.size,
              backgroundColor: moneyColor,
              opacity: particleOpacity,
              transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
              borderRadius: 2,
              filter: `hue-rotate(${p.hueShift}deg)`,
            }}
          />
        );
      })}

      {/* 2. Main Glowing Dollar Sign */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10, // On top of spray
        }}
      >
        <div
          style={{
            transform: `scale(${scale})`,
            opacity,
            filter: `drop-shadow(0 0 ${glowRadius}px ${glowColor})`,
          }}
        >
          <DollarSign
            size={iconSize}
            color={dollarColor}
            strokeWidth={2.5}
          />
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default MoneySpray;